#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maximumSum(vector<int>& arr) {
        int n = arr.size();
        int noDelete = arr[0], oneDelete = 0, maxSum = arr[0];
        for (int i = 1; i < n; i++) {
            oneDelete = max(noDelete, oneDelete + arr[i]);
            noDelete = max(arr[i], noDelete + arr[i]);
            maxSum = max({maxSum, noDelete, oneDelete});
        }
        return maxSum;
    }
};
